; ================================================================
;            PROVIDED TEST HARNESS -- DO NOT EDIT THIS FILE
; ================================================================
;
; Reads three lines from stdin:
;     line 1: fmt
;     line 2: arg
;     line 3: cap (decimal, at most 4096)
; calls fmt_replace(fmt, arg, out, cap) and prints
;     line 1: the string fmt_replace left in out
;     line 2: the value it returned in rax
; Before the call every byte of out is set to '#'. After the call the
; harness prints an ERROR line if out has no NUL in its first cap bytes,
; or if any byte at out[cap] or beyond was changed.
; If the cap line has more text after the number (the hidden tests use
; "64 regs"), it also prints an ERROR line for every callee-saved register
; (rbx, rbp, r12-r15, rsp) that fmt_replace did not preserve.

    global _start
    extern fmt_replace

INSZ  equ 8192
OUTSZ equ 4096
GUARD equ 64                    ; extra bytes after out, to catch writes past cap
FILL  equ '#'

section .bss
    inbuf   resb INSZ
    outbuf  resb OUTSZ + GUARD
    numbuf  resb 32
    saved   resq 3                  ; fmt, arg, cap while the registers hold sentinels
    after   resq 7                  ; rbx, rbp, r12-r15, rsp right after the call
    rsp_in  resq 1                  ; rsp right before the call
    chkregs resb 1                  ; 1 = check the callee-saved registers

section .rodata
    msg_nonul   db "ERROR: out has no NUL in its first cap bytes", 10
    len_nonul   equ $ - msg_nonul
    msg_past    db "ERROR: a byte at out[cap] or beyond was changed", 10
    len_past    equ $ - msg_past
    msg_cap     db "ERROR: cap must be at most 4096", 10
    len_cap     equ $ - msg_cap
    msg_reg     db "ERROR: callee-saved register "
    len_reg     equ $ - msg_reg
    msg_chg     db " was changed", 10
    len_chg     equ $ - msg_chg
    reg_names   db "rbxrbpr12r13r14r15rsp"   ; 3 bytes each, same order as after
    newline     db 10

section .data
    ; values put in the callee-saved registers before the call
    sentinels   dq 0x1111111111111111, 0x2222222222222222, 0x3333333333333333
                dq 0x4444444444444444, 0x5555555555555555, 0x6666666666666666

section .text
_start:
    ; read stdin one byte at a time until the third newline or the end of
    ; input, so it also works typed in by hand (no ^D needed). inbuf is
    ; zeroed (.bss) and one byte is kept free, so the text is always
    ; NUL-terminated
    xor     r12d, r12d              ; r12 = bytes read so far
    xor     ebx, ebx                ; rbx = newlines seen so far
.read:
    cmp     r12, INSZ - 1
    jae     .read_done
    xor     eax, eax                ; read(0, inbuf + r12, 1)
    xor     edi, edi
    lea     rsi, [rel inbuf]
    add     rsi, r12
    mov     edx, 1
    syscall
    test    rax, rax
    js      .die
    jz      .read_done              ; 0 = end of input
    inc     r12
    cmp     byte [rsi], 10
    jne     .read
    inc     ebx
    cmp     ebx, 3
    jb      .read
.read_done:

    ; split the input into lines
    lea     rdi, [rel inbuf]
    mov     r13, rdi                ; r13 = fmt
    call    cut_line
    mov     r14, rax                ; r14 = arg
    mov     rdi, rax
    call    cut_line
    mov     rdi, rax
    call    parse_u64
    mov     r15, rax                ; r15 = cap
    movzx   eax, byte [rdi]         ; more text after the number: check registers
    test    al, al
    jz      .no_regs
    cmp     al, 10
    je      .no_regs
    mov     byte [rel chkregs], 1
.no_regs:
    cmp     r15, OUTSZ
    ja      .bad_cap

    ; fill out and the guard bytes after it with '#'
    lea     rdi, [rel outbuf]
    xor     ecx, ecx
.fill:
    mov     byte [rdi + rcx], FILL
    inc     rcx
    cmp     rcx, OUTSZ + GUARD
    jb      .fill

    mov     [rel saved], r13
    mov     [rel saved + 8], r14
    mov     [rel saved + 16], r15
    mov     rdi, r13
    mov     rsi, r14
    lea     rdx, [rel outbuf]
    mov     rcx, r15
    mov     rbx, [rel sentinels]
    mov     rbp, [rel sentinels + 8]
    mov     r12, [rel sentinels + 16]
    mov     r13, [rel sentinels + 24]
    mov     r14, [rel sentinels + 32]
    mov     r15, [rel sentinels + 40]
    mov     [rel rsp_in], rsp
    mov     rax, -1                 ; junk, so never setting rax cannot pass by luck
    call    fmt_replace
    mov     [rel after], rbx
    mov     [rel after + 8], rbp
    mov     [rel after + 16], r12
    mov     [rel after + 24], r13
    mov     [rel after + 32], r14
    mov     [rel after + 40], r15
    mov     [rel after + 48], rsp
    mov     rsp, [rel rsp_in]       ; continue with the harness's own stack
    mov     rbx, rax                ; rbx = returned value
    mov     r13, [rel saved]
    mov     r14, [rel saved + 8]
    mov     r15, [rel saved + 16]

    ; line 1: out up to its NUL (cap = 0 means out is empty)
    test    r15, r15
    jz      .empty
    lea     rsi, [rel outbuf]
    xor     edx, edx                ; rdx = index of the NUL
.find_nul:
    cmp     rdx, r15
    jae     .no_nul
    cmp     byte [rsi + rdx], 0
    je      .print_out
    inc     rdx
    jmp     .find_nul
.print_out:
    call    write_out
.empty:
    lea     rsi, [rel newline]
    mov     edx, 1
    call    write_out
    jmp     .print_ret
.no_nul:
    lea     rsi, [rel msg_nonul]
    mov     edx, len_nonul
    call    write_out

    ; line 2: the returned value
.print_ret:
    mov     rdi, rbx
    call    print_u64

    ; out[cap] .. end of the guard must still be '#'
    lea     rsi, [rel outbuf]
    mov     rcx, r15
.check_guard:
    cmp     rcx, OUTSZ + GUARD
    jae     .check_regs
    cmp     byte [rsi + rcx], FILL
    jne     .past
    inc     rcx
    jmp     .check_guard
.past:
    lea     rsi, [rel msg_past]
    mov     edx, len_past
    call    write_out

    ; callee-saved registers: after[k] must equal sentinels[k], rsp must be rsp_in
.check_regs:
    cmp     byte [rel chkregs], 0
    je      .exit_ok
    xor     r12d, r12d              ; r12 = k
.next_reg:
    cmp     r12, 7
    jae     .exit_ok
    lea     rax, [rel after]
    mov     rax, [rax + r12*8]
    lea     rcx, [rel rsp_in]       ; for k = 6 compare with rsp_in
    cmp     r12, 6
    je      .cmp_reg
    lea     rcx, [rel sentinels]
    lea     rcx, [rcx + r12*8]
.cmp_reg:
    cmp     rax, [rcx]
    je      .reg_ok
    lea     rsi, [rel msg_reg]
    mov     edx, len_reg
    call    write_out
    lea     rsi, [rel reg_names]
    lea     rsi, [rsi + r12*2]
    add     rsi, r12                ; reg_names + 3k
    mov     edx, 3
    call    write_out
    lea     rsi, [rel msg_chg]
    mov     edx, len_chg
    call    write_out
.reg_ok:
    inc     r12
    jmp     .next_reg

.exit_ok:
    xor     edi, edi                ; exit(0)
    mov     eax, 60
    syscall
.bad_cap:
    lea     rsi, [rel msg_cap]
    mov     edx, len_cap
    call    write_out
.die:
    mov     edi, 1                  ; exit(1)
    mov     eax, 60
    syscall

; cut_line(char* p{rdi}) -> char*{rax}
; ends the line at p with a NUL and returns the start of the next line
; (at the end of the input it returns the end, so later lines are empty)
cut_line:
    movzx   eax, byte [rdi]
    test    al, al
    jz      .end
    cmp     al, 10
    je      .newline
    inc     rdi
    jmp     cut_line
.newline:
    mov     byte [rdi], 0
    inc     rdi
.end:
    mov     rax, rdi
    ret

; parse_u64(const char* p{rdi}) -> uint64_t{rax}: decimal digits at p
parse_u64:
    xor     eax, eax
.digit:
    movzx   ecx, byte [rdi]
    sub     ecx, '0'
    cmp     ecx, 9
    ja      .done                   ; not '0'..'9'
    imul    rax, 10
    add     rax, rcx
    inc     rdi
    jmp     .digit
.done:
    ret

; write_out(const char* buf{rsi}, size_t len{rdx}): write(1, buf, len)
write_out:
    mov     eax, 1
    mov     edi, 1
    syscall
    ret

; print_u64(uint64_t x{rdi}): x in decimal and a newline
print_u64:
    lea     rsi, [rel numbuf + 32]
    dec     rsi
    mov     byte [rsi], 10
    mov     rax, rdi
    mov     r8d, 10
.emit:
    xor     edx, edx
    div     r8
    add     dl, '0'
    dec     rsi
    mov     [rsi], dl
    test    rax, rax
    jnz     .emit
    lea     rdx, [rel numbuf + 32]
    sub     rdx, rsi
    jmp     write_out
